/**
 * The app's one source of truth for "what Pokémon exist, what are they called, what type are they, what forms
 * do they come in" — built from `POKEDEX_DATA`, `FORM_TYPE_OVERRIDES` and `POKEDEX_FORMS`
 * (constants/pokedex-data.ts, generated by `npm run pokedex:generate` from PokeAPI's CSVs plus PokeMiners'
 * game master; see that file's header).
 * Nothing here is typed from memory (AGENTS.md: never hallucinate game data): a name, dex number or type
 * that doesn't appear in the generated data cannot be looked up or searched.
 *
 * TYPES ARE PER (pokemonId, formCode), NOT PER SPECIES. Zacian is Fairy, but Crowned Sword Zacian is
 * Fairy/Steel; Alolan Vulpix is Ice where Vulpix is Fire; Galarian Slowpoke drops Water. Every creature in
 * the app carries `pokemonId` + `formCode`, so ask `typesOf(creature)`; `PokedexEntry.types` is only the
 * species' DEFAULT form. A type filter asks `typeMembership(type)` (or `creatureHasType` client-side).
 * `PokedexEntry.hue` is `TYPE_HUE[types[0]]`, i.e. the species' primary type.
 */
import { FORM_TYPE_OVERRIDES, POKEDEX_DATA, POKEDEX_DEFAULT_FORMS, POKEDEX_FORMS } from './pokedex-data';
import { POKEMON_TYPES, formatTypes, type PokemonType, type PokemonTypes } from './pokemon-types';

// The type vocabulary lives in a leaf module (the generator and the generated data import it without
// importing the dex). Import it from HERE in app code, so there is one import site.
export { POKEMON_TYPES, formatTypes };
export type { PokemonType, PokemonTypes };

export interface PokedexEntry {
  pokemonId: number;
  name: string;
  /** The species' DEFAULT form's types: one or two, primary first. NOT form-aware: use `typesOf` for a
   *  creature that may carry a `formCode`. */
  types: PokemonTypes;
  /** `TYPE_HUE[types[0]]`. */
  hue: number;
}

/**
 * Design mapping of type -> accent hue (0-360), for the hue-driven chip/card backgrounds in
 * `constants/theme.ts` (`hueChipBg`, `hueBleed`, ...). Seven values are pinned to hues already in use
 * for specific Pokémon elsewhere in the app (CreateListingModal's demo creatures, data/listings.ts) so a
 * type-derived hue never clashes with one a screen already hardcodes: Fire 18 (Charizard/Moltres), Water
 * 205 (Blastoise), Grass 130 (Venusaur), Electric 48 (Zapdos), Ice 210 (Articuno), Dragon 205 (Dragonite —
 * shares Water's blue, which is how the mock data already draws it), Psychic 275 (Mewtwo).
 *
 * The rest are chosen to group by the same warm/cool families those seven already sketch out:
 *   - warm earth tones (Normal, Fighting, Ground, Rock, plus Fire/Electric above)
 *   - green (Bug, plus Grass above)
 *   - blue (plus Water/Ice/Dragon above)
 *   - blue-violet "mystical" cluster (Flying, Steel, Ghost, Dark, plus Psychic above)
 *   - pink-violet (Poison, Fairy)
 */
export const TYPE_HUE: Record<PokemonType, number> = {
  Fighting: 5,
  Ground: 35,
  Rock: 42,
  Normal: 45,
  Fire: 18,
  Electric: 48,
  Bug: 85,
  Grass: 130,
  Water: 205,
  Dragon: 205,
  Ice: 210,
  Steel: 220,
  Flying: 230,
  Ghost: 255,
  Dark: 265,
  Psychic: 275,
  Poison: 295,
  Fairy: 330,
};

/** Built once from `POKEDEX_DATA`; every list, lookup and search below reads from this. */
export const POKEDEX: readonly PokedexEntry[] = POKEDEX_DATA.map(([pokemonId, name, types]) => ({
  pokemonId,
  name,
  types,
  hue: TYPE_HUE[types[0]],
}));

const BY_ID = new Map<number, PokedexEntry>(POKEDEX.map((entry) => [entry.pokemonId, entry]));

export function findPokemon(pokemonId: number): PokedexEntry | undefined {
  return BY_ID.get(pokemonId);
}

// ——— types (form-aware) ———

/** Anything that identifies a creature for typing: `CreatureRef`, `Listing`, `FormalOffer` all fit. */
export interface TypedCreature {
  pokemonId: number;
  /** PokeMiners form code, exact spelling (`'CROWNED_SWORD'`, `'ALOLA'`, `'MEGA_X'`). Absent/null = the
   *  species' default form. */
  formCode?: string | null;
}

const overrideKey = (pokemonId: number, formCode: string) => `${pokemonId}:${formCode}`;

/** `pokemonId:formCode` -> the typing of forms that differ from their species' default. */
const FORM_TYPES = new Map<string, PokemonTypes>(FORM_TYPE_OVERRIDES.map(([id, code, types]) => [overrideKey(id, code), types]));

/**
 * The types of this creature: the form's own typing when `FORM_TYPE_OVERRIDES` lists `(pokemonId, formCode)`,
 * otherwise the species' default typing (so a null/absent form code, and a form that doesn't change typing,
 * such as Hero Zacian or an event costume, both resolve to the species). `undefined` ONLY when `pokemonId`
 * is not a dex species: synthetic and unknown ids exist, and this never guesses a type for them.
 *
 * `formCode` must use PokeMiners' exact spelling (case-sensitive). An unrecognised code falls back to the
 * species typing rather than failing, because a form the data doesn't know about has no override.
 *
 * Order is the data source's: index 0 is the primary type, e.g. `['Fire', 'Flying']` for Charizard and
 * `['Fairy', 'Steel']` for Crowned Sword Zacian (PokeAPI and the game master list Fairy first).
 */
export function typesOf(creature: TypedCreature): PokemonTypes | undefined {
  const species = BY_ID.get(creature.pokemonId);
  if (!species) return undefined;
  return (creature.formCode ? FORM_TYPES.get(overrideKey(creature.pokemonId, creature.formCode)) : undefined) ?? species.types;
}

/** Whether the creature has `type` in either slot. False for an id outside the dex. */
export function creatureHasType(creature: TypedCreature, type: PokemonType): boolean {
  return typesOf(creature)?.includes(type) ?? false;
}

/**
 * Every creature that has a given type, as three disjoint groups that compile directly into a query on
 * `listings (pokemon_id, form_code)`. A row (pokemonId, formCode) HAS the type exactly when ONE of:
 *
 *   1. `pokemonId` is in `allForms`. These species' default typing has the type and none of their forms
 *      drop it, so the row matches whatever its `formCode` is (including null).
 *   2. `pokemonId` has an entry in `exceptForms` and the row's `formCode` is NOT in its `formCodes`
 *      (null counts as "not in"). These species' default typing has the type, but those forms drop it:
 *      Vulpix is Fire, Alolan Vulpix is Ice, so Fire matches Vulpix and every other Vulpix form, but not ALOLA.
 *   3. `pokemonId` has an entry in `onlyForms` and the row's `formCode` IS in its `formCodes`. These
 *      species' default typing lacks the type, but those forms gain it: Rotom is Electric/Ghost, Heat Rotom
 *      is Electric/Fire, so Fire matches Rotom only with formCode HEAT, and never with a null formCode.
 *
 * It is exactly `creatureHasType(row, type)` for every dex species and every form code, which
 * `pokedex.test.ts` verifies exhaustively. Ids outside the dex match nothing (as `typesOf` is undefined).
 * Mega and Primal forms are in the table like any other form (`MEGA`, `MEGA_X`, `MEGA_Y`, `PRIMAL`).
 *
 * As a PostgREST `or` filter (supabase-js `.or(...)`), for Fire it looks like:
 *
 *     pokemon_id.in.(4,5,6,...),                                          // allForms
 *     and(pokemon_id.eq.37,or(form_code.is.null,form_code.not.in.(ALOLA))), // one exceptForms entry
 *     and(pokemon_id.eq.479,form_code.in.(HEAT))                          // one onlyForms entry
 *
 * The `form_code.is.null` branch is essential: SQL's `NOT IN` is never true for NULL, so without it a
 * Vulpix listing with no form would wrongly stop matching Fire. Form codes are `[A-Z0-9_]+`, so they need no
 * PostgREST value quoting. `listings.pokemon_id` and `.form_code` are the only columns involved, and no
 * migration is needed. Combine several selected types by OR-ing their clauses (a union).
 *
 * Built once at module load; the same object is returned every call, so treat it as immutable.
 */
export interface TypeMembership {
  type: PokemonType;
  /** Species ids, ascending. */
  allForms: readonly number[];
  exceptForms: readonly { pokemonId: number; formCodes: readonly string[] }[];
  onlyForms: readonly { pokemonId: number; formCodes: readonly string[] }[];
}

const MEMBERSHIPS: ReadonlyMap<PokemonType, TypeMembership> = (() => {
  const formsBySpecies = new Map<number, [formCode: string, types: PokemonTypes][]>();
  for (const [pokemonId, formCode, types] of FORM_TYPE_OVERRIDES) {
    const forms = formsBySpecies.get(pokemonId) ?? [];
    forms.push([formCode, types]);
    formsBySpecies.set(pokemonId, forms);
  }

  const byType = new Map<PokemonType, TypeMembership>();
  for (const type of POKEMON_TYPES) {
    const allForms: number[] = [];
    const exceptForms: { pokemonId: number; formCodes: string[] }[] = [];
    const onlyForms: { pokemonId: number; formCodes: string[] }[] = [];
    for (const { pokemonId, types } of POKEDEX) {
      const forms = formsBySpecies.get(pokemonId) ?? [];
      if (types.includes(type)) {
        const dropped = forms.filter(([, formTypes]) => !formTypes.includes(type)).map(([code]) => code);
        if (dropped.length === 0) allForms.push(pokemonId);
        else exceptForms.push({ pokemonId, formCodes: dropped });
      } else {
        const gained = forms.filter(([, formTypes]) => formTypes.includes(type)).map(([code]) => code);
        if (gained.length > 0) onlyForms.push({ pokemonId, formCodes: gained });
      }
    }
    byType.set(type, { type, allForms, exceptForms, onlyForms });
  }
  return byType;
})();

export function typeMembership(type: PokemonType): TypeMembership {
  const membership = MEMBERSHIPS.get(type);
  if (!membership) throw new Error(`Unknown Pokémon type: ${String(type)}`); // unreachable for a typed caller
  return membership;
}

// ——— forms (which forms a creature can be listed as) ———

const NO_FORMS: readonly string[] = [];

/** `pokemonId` -> its selectable non-default form codes, in the game master's order. */
const FORMS_BY_SPECIES = new Map<number, readonly string[]>(POKEDEX_FORMS);

/** `pokemonId` -> the form code of a default form that has a name of its own. */
const DEFAULT_FORM_BY_SPECIES = new Map<number, string>(POKEDEX_DEFAULT_FORMS);

/**
 * The forms a creature of this species can be listed as, besides its default: `CreatureRef.formCode` values in
 * PokeMiners' exact spelling, in the game master's own order (`[]` for a species with only one form, and for an
 * id outside the dex). `formCode: null` is the default form and is never in this list, so a form picker offers
 * "the default" plus these.
 *
 * This is the COMPLETE list of what a trainer can pick, which `FORM_TYPE_OVERRIDES` is not: that table holds
 * only the forms whose TYPING differs (Alolan Vulpix), so Origin Palkia and Armored Mewtwo, which type like
 * their species, are only here. What is left out (the default, event costumes, shadow variants, Mega/Primal) and
 * why is documented in the header of `constants/pokedex-data.ts`, where the list is generated.
 *
 * It does NOT say whether a form can be traded: ask `isPokemonUntradable(pokemonId, formCode)` for each, since
 * the Deoxys forms are listed here although every Deoxys is untradable, and White Kyurem is listed although
 * Kyurem is not.
 */
export function formsOf(pokemonId: number): readonly string[] {
  return FORMS_BY_SPECIES.get(pokemonId) ?? NO_FORMS;
}

/**
 * The form code `formCode: null` stands for on this species, when that form has a name of its own (Zacian's
 * `HERO`, Giratina's `ALTERED`, Vivillon's `MEADOW`), so a picker can label its "default" choice with it.
 * `undefined` when the default is the plain `*_NORMAL` form (nothing better to say than "Standard"), for a
 * species with no selectable forms, and for an id outside the dex. It is for LABELS ONLY: a creature in the
 * default form still carries `formCode: null`, never this code, so the same creature is never stored two ways.
 */
export function defaultFormOf(pokemonId: number): string | undefined {
  return DEFAULT_FORM_BY_SPECIES.get(pokemonId);
}

// ——— trade eligibility ———
// The client half of a rule the database enforces too: `public.is_creature_untradable` in
// supabase/migrations/20260929000100_enforce_untradable_pokemon.sql holds the SAME three lists, and
// `pokedex.test.ts` fails if the two drift apart. Shadow Pokémon are untradable as well, but that rule has no
// entry here because no creature shape in the app can carry "shadow" at all (`listings.bg <> 'shadow'`,
// and `CreatureRef`/`FormalOffer` have no shadow flag).

/** Mythicals can't be traded in Pokémon GO. Meltan (808) and Melmetal (809) are the one exception and are
 *  deliberately absent. */
export const UNTRADABLE_MYTHICAL_IDS: ReadonlySet<number> = new Set([
  151, // Mew
  251, // Celebi
  385, // Jirachi
  386, // Deoxys (all forms)
  489, // Phione
  490, // Manaphy
  491, // Darkrai
  492, // Shaymin
  493, // Arceus
  494, // Victini
  647, // Keldeo
  648, // Meloetta
  649, // Genesect
  719, // Diancie
  720, // Hoopa
  721, // Volcanion
  801, // Magearna
  802, // Marshadow
  807, // Zeraora
  893, // Zarude
  1025, // Pecharunt
]);

/** Non-mythical species that are untradable in every form. */
export const UNTRADABLE_SPECIES_IDS: ReadonlySet<number> = new Set([
  718, // Zygarde
]);

/** Fused forms, keyed by PokeMiners form code (`CreatureRef.formCode`). The unfused species stays tradable. */
export const UNTRADABLE_FORM_COMBINATIONS: readonly { pokemonId: number; formCode: string }[] = [
  { pokemonId: 646, formCode: 'WHITE' }, // White Kyurem
  { pokemonId: 646, formCode: 'BLACK' }, // Black Kyurem
  { pokemonId: 800, formCode: 'DUSK_MANE' }, // Dusk Mane Necrozma
  { pokemonId: 800, formCode: 'DAWN_WINGS' }, // Dawn Wings Necrozma
];

/** Whether this species (and form) can never change hands in Pokémon GO, so it must never be listed,
 *  wanted in return, or formally offered. */
export function isPokemonUntradable(pokemonId: number, formCode?: string | null): boolean {
  if (UNTRADABLE_MYTHICAL_IDS.has(pokemonId) || UNTRADABLE_SPECIES_IDS.has(pokemonId)) return true;
  return formCode != null && UNTRADABLE_FORM_COMBINATIONS.some((c) => c.pokemonId === pokemonId && c.formCode === formCode);
}

/**
 * Case- and diacritic-insensitive, punctuation-stripping search key: "Flabébé" -> "flabebe",
 * "Mr. Mime" -> "mrmime", "Farfetch’d" -> "farfetchd", "Type: Null" -> "typenull". Diacritics are
 * removed via Unicode decomposition (NFD) rather than a hand-rolled accent table, so it holds for any
 * future entry, not just the ones spot-checked when this was written.
 */
function searchKey(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // combining diacritical marks left behind by NFD
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

const SEARCH_KEYS = new Map<number, string>(POKEDEX.map((entry) => [entry.pokemonId, searchKey(entry.name)]));

/** A query of only digits (an optional leading '#' and leading zeros allowed) is a dex-number search. */
function numericQuery(raw: string): string | null {
  const trimmed = raw.trim().replace(/^#/, '');
  if (trimmed.length === 0 || !/^\d+$/.test(trimmed)) return null;
  const stripped = trimmed.replace(/^0+/, '');
  return stripped.length === 0 ? '0' : stripped;
}

const DEFAULT_SEARCH_LIMIT = 30;

/**
 * Ranked search over the whole dex: numeric queries match the dex number (exact, then prefix);
 * text queries match the name (exact, then prefix, then anywhere), all case/diacritic/punctuation
 * -insensitive. An empty query returns the start of the dex, so callers don't need a separate branch
 * for "nothing typed yet" (see PokemonPickerModal's empty state).
 */
export function searchPokedex(query: string, limit = DEFAULT_SEARCH_LIMIT): PokedexEntry[] {
  const trimmed = query.trim();
  if (trimmed.length === 0) return POKEDEX.slice(0, limit);

  const digits = numericQuery(trimmed);
  const key = searchKey(trimmed);

  const ranked: { entry: PokedexEntry; rank: number }[] = [];
  for (const entry of POKEDEX) {
    let rank = Infinity;
    if (digits !== null) {
      const idStr = String(entry.pokemonId);
      if (idStr === digits) rank = 0;
      else if (idStr.startsWith(digits)) rank = 1;
    }
    if (key.length > 0) {
      const nameKey = SEARCH_KEYS.get(entry.pokemonId) ?? '';
      if (nameKey === key) rank = Math.min(rank, 2);
      else if (nameKey.startsWith(key)) rank = Math.min(rank, 3);
      else if (nameKey.includes(key)) rank = Math.min(rank, 4);
    }
    if (rank !== Infinity) ranked.push({ entry, rank });
  }

  ranked.sort((a, b) => (a.rank !== b.rank ? a.rank - b.rank : a.entry.pokemonId - b.entry.pokemonId));
  return ranked.slice(0, limit).map((r) => r.entry);
}
